WITH cleaned AS (SELECT *, COALESCE(amount, 0) AS amount_filled, CONCAT_WS('-', status, method) AS status_method_key, COALESCE(method, 'N/A') AS resolved_method FROM payments WHERE paid_at >= TIMESTAMP '2023-09-06 13:00:00' AND method IS NOT NULL) SELECT * FROM (SELECT order_id, status, amount FROM cleaned) src PIVOT (MAX(amount) AS amount, COUNT(1) AS item_count FOR status IN ('FAILED', 'REFUNDED'));
